<script lang="ts">import AcademicEmptyState from '$lib/components/academic/AcademicEmptyState.svelte'; import AcademicErrorState from '$lib/components/academic/AcademicErrorState.svelte'; import SourceBadge from '$lib/components/academic/SourceBadge.svelte'; import PageHeader from '$lib/components/shell/PageHeader.svelte'; let { data } = $props(); const dt = new Intl.DateTimeFormat('en-PH', { dateStyle: 'medium', timeStyle: 'short', timeZone: 'Asia/Manila' });</script>
<svelte:head><title>Academic Events · IMS Academic Hub</title></svelte:head>
